/* Make label fully visible on hover */
.md-content__button[href*="edit"]:hover::after {
  opacity: 1;
}

/* Hide edit button on generated docs/examples pages */
@media (min-width: 960px) {
  .md-content__button[href*="docs/examples/"] {
    display: none !important;
  }
}

.md-content__button-wrapper {
  position: absolute;
  top: 0.6rem;
  right: 0.8rem;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 0.4rem;
  z-index: 1;
}

.md-content__button-wrapper a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 24px;
  width: 24px;
  color: var(--md-default-fg-color);
  text-decoration: none;
}

.md-content__button-wrapper a:hover {
  color: var(--md-accent-fg-color);
}

/* Slack and Forum css */
.slack-button, 
.forum-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 0.4rem;
  height: 24px;
}

.slack-button img {
  height: 18px;
  filter: none !important;
}

.slack-button:hover,
.forum-button:hover {
  opacity: 0.7;
}

.forum-button svg {
  height: 28px;
  opacity: 0.9;
  transform: translateY(2px);
}

/* For logo css */
[data-md-color-scheme="default"] .logo-dark {
  display: none;
}

[data-md-color-scheme="slate"] .logo-light {
  display: none;
}

/* Outline for content tabs */
.md-typeset .tabbed-set {
  border: 0.075rem solid var(--md-default-fg-color);
  border-radius: 0.2rem;
}

.md-typeset .tabbed-content {
  padding: 0 0.6em;
